"use strict";(self.webpackChunkaegis_docs=self.webpackChunkaegis_docs||[]).push([[215],{8437:(e,i,a)=>{a.r(i),a.d(i,{assets:()=>c,contentTitle:()=>o,default:()=>h,frontMatter:()=>t,metadata:()=>n,toc:()=>l});const n=JSON.parse('{"id":"what-is-aegis","title":"What is Aegis?","description":"Aegis is an internal researcher-ranking engine built for labeling tasks. Given a specialty query \u2014 say, \\"non-small-cell lung cancer translational research\\" \u2014 Aegis returns a ranked list of the top K candidates, each with a composite score, per-component evidence trail, and integrity flags. The system is designed for internal task managers who need to identify and vet researchers quickly, not as a researcher-facing product.","source":"@site/docs/what-is-aegis.mdx","sourceDirName":".","slug":"/what-is-aegis","permalink":"/aegis/docs/what-is-aegis","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"What is Aegis?"},"sidebar":"docsSidebar","next":{"title":"Submitting a Query","permalink":"/aegis/docs/using-aegis/submitting-a-query"}}');var s=a(4848),r=a(8453);const t={sidebar_position:1,title:"What is Aegis?"},o="What is Aegis?",c={},l=[{value:"The Problem",id:"the-problem",level:2},{value:"What Aegis Produces",id:"what-aegis-produces",level:2},{value:"Who Uses Aegis",id:"who-uses-aegis",level:2},{value:"How Scoring Works",id:"how-scoring-works",level:2},{value:"Three Researcher Populations",id:"three-researcher-populations",level:2},{value:"Translational",id:"translational",level:3},{value:"Drug Discovery",id:"drug-discovery",level:3},{value:"Clinician",id:"clinician",level:3}];function d(e){const i={h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(i.header,{children:(0,s.jsx)(i.h1,{id:"what-is-aegis",children:"What is Aegis?"})}),"\n",(0,s.jsx)(i.p,{children:'Aegis is an internal researcher-ranking engine built for labeling tasks. Given a specialty query \u2014 say, "non-small-cell lung cancer translational research" \u2014 Aegis returns a ranked list of the top K candidates, each with a composite score, per-component evidence trail, and integrity flags. The system is designed for internal task managers who need to identify and vet researchers quickly, not as a researcher-facing product.'}),"\n",(0,s.jsx)(i.h2,{id:"the-problem",children:"The Problem"}),"\n",(0,s.jsx)(i.p,{children:"Healthcare, biomedical research, and drug discovery span millions of active researchers worldwide. They publish papers, file patents, secure grants, lead clinical trials, and hold board certifications \u2014 all tracked across dozens of disconnected data sources. When a task manager needs to find the best researchers in a narrow specialty, the challenge is not a lack of data. The challenge is synthesizing that data into a defensible, transparent ranking that accounts for research quality, topical relevance, recency, and professional integrity."}),"\n",(0,s.jsx)(i.p,{children:"Manual approaches do not scale. Keyword searches across PubMed or patent databases return noisy results without any notion of quality or fit. Existing researcher profiles (Google Scholar, ORCID) are self-reported and incomplete. No single source captures the full picture of a researcher's standing across publications, funding, clinical work, and integrity history."}),"\n",(0,s.jsx)(i.p,{children:"Aegis solves this by ingesting data from approximately 20 sources, resolving researcher identities across them, and computing a multi-dimensional ranking that balances quality, relevance, recency, and integrity."}),"\n",(0,s.jsx)(i.h2,{id:"what-aegis-produces",children:"What Aegis Produces"}),"\n",(0,s.jsx)(i.p,{children:"For a given specialty query, Aegis produces:"}),"\n",(0,s.jsxs)(i.ul,{children:["\n",(0,s.jsxs)(i.li,{children:[(0,s.jsx)(i.strong,{children:"A ranked list of K candidates"})," ordered by composite score, where K is configurable per query."]}),"\n",(0,s.jsxs)(i.li,{children:[(0,s.jsx)(i.strong,{children:"Per-candidate scores"})," broken down by component so that every ranking decision is transparent and auditable."]}),"\n",(0,s.jsxs)(i.li,{children:[(0,s.jsx)(i.strong,{children:"Evidence trails"})," linking each score component back to the underlying data: specific publications, grants, patents, clinical trials, or integrity records."]}),"\n",(0,s.jsxs)(i.li,{children:[(0,s.jsx)(i.strong,{children:"Integrity flags"})," indicating whether a candidate has been hard-excluded (for reasons such as federal debarment or confirmed research fraud) or received soft scoring discounts (for issues such as retracted co-authorships or predatory journal publications)."]}),"\n",(0,s.jsxs)(i.li,{children:[(0,s.jsx)(i.strong,{children:"A job tracking system"})," that lets task managers submit queries and immediately move on. Progress is visible in real time through the Jobs dashboard."]}),"\n",(0,s.jsxs)(i.li,{children:[(0,s.jsx)(i.strong,{children:"Shortlists and notes"})," for organizing and annotating candidates across team members."]}),"\n"]}),"\n",(0,s.jsx)(i.h2,{id:"who-uses-aegis",children:"Who Uses Aegis"}),"\n",(0,s.jsx)(i.p,{children:"Aegis serves internal task managers. These are the people responsible for identifying, vetting, and engaging researchers for labeling tasks. Aegis is not researcher-facing \u2014 candidates do not interact with the system, view their own scores, or manage profiles. Task managers use Aegis to go from a specialty description to a shortlist of vetted candidates, replacing manual searches and spreadsheet-based tracking."}),"\n",(0,s.jsx)(i.h2,{id:"how-scoring-works",children:"How Scoring Works"}),"\n",(0,s.jsx)(i.p,{children:"Every candidate receives a composite score built from four components:"}),"\n",(0,s.jsxs)(i.ul,{children:["\n",(0,s.jsxs)(i.li,{children:[(0,s.jsx)(i.strong,{children:"Recency (R):"})," How recent and active is the candidate's work in the queried specialty? A researcher with five papers in the last two years scores higher than one whose last publication was a decade ago."]}),"\n",(0,s.jsxs)(i.li,{children:[(0,s.jsx)(i.strong,{children:"Quality Prior (Q):"})," How strong is the candidate's overall research profile, independent of any specific query? This is a composite of six sub-scores (seven for clinicians) covering citation impact, funding track record, leadership roles, apex-list membership, translational output, and academic lineage."]}),"\n",(0,s.jsxs)(i.li,{children:[(0,s.jsx)(i.strong,{children:"Topical Fit (C):"})," How closely does the candidate's body of work align with the specific specialty being queried? A researcher who publishes broadly in oncology may score lower on topical fit for a narrow immunotherapy query than a specialist in that exact subfield."]}),"\n",(0,s.jsxs)(i.li,{children:[(0,s.jsx)(i.strong,{children:"Integrity Gate (I):"})," Does the candidate pass integrity checks? Hard gates \u2014 federal debarment, confirmed fraud, sanctions-list matches \u2014 exclude a candidate entirely. Soft discounts \u2014 retracted co-authorships, predatory journal publications, paper-mill associations \u2014 reduce the score proportionally rather than eliminating the candidate."]}),"\n"]}),"\n",(0,s.jsx)(i.p,{children:"These four components combine into a single composite score. The Quality Prior uses a geometric mean of its sub-scores, which naturally penalizes candidates who are strong in one area but weak in others. A well-rounded researcher scores higher than one with a single exceptional metric and several poor ones."}),"\n",(0,s.jsx)(i.p,{children:"The exponents that control how much weight each component receives are not hand-tuned. They are learned from expert pairwise judgments through a feedback loop: domain experts compare pairs of candidates, and a statistical model (Plackett-Luce) fits the exponents to match those judgments. This means the ranking improves over time as more expert input is collected."}),"\n",(0,s.jsx)(i.h2,{id:"three-researcher-populations",children:"Three Researcher Populations"}),"\n",(0,s.jsx)(i.p,{children:"Not all researchers are the same. A clinical oncologist, a medicinal chemist, and a translational biologist each have different kinds of evidence supporting their expertise. Aegis handles this by defining three distinct populations, each with its own weight vector learned independently:"}),"\n",(0,s.jsx)(i.h3,{id:"translational",children:"Translational"}),"\n",(0,s.jsx)(i.p,{children:"Translational researchers bridge basic science and clinical application. Their evidence comes primarily from PubMed publications, NIH grants and OpenAlex-indexed international grants, clinical trial participation, and citation metrics. The quality prior for this population emphasizes citation impact, funding, and translational output \u2014 the ability to move findings from bench to bedside."}),"\n",(0,s.jsx)(i.h3,{id:"drug-discovery",children:"Drug Discovery"}),"\n",(0,s.jsx)(i.p,{children:"Drug-discovery researchers work in pharmaceutical and biotech contexts. Their evidence comes primarily from patents (USPTO, EPO, WIPO), chemical biology databases like ChEMBL, and translational publications. The quality prior for this population heavily weights patent-derived translational impact, reflecting that intellectual property is the primary output measure in this domain."}),"\n",(0,s.jsx)(i.h3,{id:"clinician",children:"Clinician"}),"\n",(0,s.jsx)(i.p,{children:"Clinicians are practicing physicians involved in research. Their evidence comes from medical licenses (NPI/NPPES), board certifications (ABMS), hospital affiliations and tier rankings, clinical trial leadership, procedure volumes, and publications. This population uses an additional seventh sub-score in the quality prior \u2014 the clinician-specific F7 score \u2014 which synthesizes board certification status, license standing, hospital tier, trial PI roles, and procedure volume into a single metric."}),"\n",(0,s.jsx)(i.p,{children:"Each population has its own weight configuration, and the exponents within each are learned independently from population-specific expert judgments. This means the system can correctly value a strong patent portfolio for a drug-discovery researcher without penalizing a translational researcher who has no patents but a strong publication record."})]})}function h(e={}){const{wrapper:i}={...(0,r.R)(),...e.components};return i?(0,s.jsx)(i,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},8453:(e,i,a)=>{a.d(i,{R:()=>t,x:()=>o});var n=a(6540);const s={},r=n.createContext(s);function t(e){const i=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(i):{...i,...e}},[i,e])}function o(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:t(e.components),n.createElement(r.Provider,{value:i},e.children)}}}]);